ALTER TABLE orders DROP CHECK ck_orders_status;
ALTER TABLE orders ADD CONSTRAINT ck_orders_status CHECK (status IN ('CREATED','PAID','CANCELLED','REFUNDED'));
CREATE TABLE payment_transactions (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,transaction_type VARCHAR(20) NOT NULL,amount DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL,reference_no VARCHAR(80) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ix_payment_transactions_order(order_id,created_at),UNIQUE KEY uq_payment_reference(reference_no),CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id),CONSTRAINT ck_payment_type CHECK(transaction_type IN('PAYMENT','REFUND')),CONSTRAINT ck_payment_status CHECK(status='APPROVED'),CONSTRAINT ck_payment_amount CHECK(amount>=0));
CREATE TABLE order_event_outbox (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,event_type VARCHAR(50) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TIMESTAMP NULL,KEY ix_order_outbox_unpublished(published_at,id),CONSTRAINT fk_order_outbox_order FOREIGN KEY(order_id) REFERENCES orders(id));
